"use client";

/**
 * Chats page — the owner's #1 ask: an OpenCode-grade chat experience.
 *
 * Two-pane layout: sidebar (folder tree + Inbox + Cmd+N new chat +
 * drag-to-folder + rename/delete) → thread. The plan/todolist/files
 * WorkspaceTabs become a collapsible right drawer, NOT a permanent
 * third pane.
 *
 * Promote to Board opens a dialog → POST /api/chats/{id}/promote →
 * success Toast with link to /board.
 * Fan out opens a dialog → POST /api/chats/{id}/spawn.
 */

import {
  useCallback,
  useEffect,
  useMemo,
  useState,
} from "react";
import {
  Button,
  Dialog,
  EmptyState,
  Icon,
  Page,
  PageHeader,
  Select,
  useToast,
} from "@/design";
import { ChatSidebar } from "@/features/chats/ChatSidebar";
import { ChatHeader } from "@/features/chats/ChatHeader";
import { ChatThread } from "@/features/chats/ChatThread";
import { WorkspaceTabs } from "@/features/chats/WorkspaceTabs";
import { useChatList, useChatFolders, useModelOptions, useSkillsForMention, useChatRefreshSignal } from "@/features/chats/useChats";
import {
  createChat as apiCreateChat,
  deleteChat as apiDeleteChat,
  promoteChat,
  spawnChat,
  updateChat as apiUpdateChat,
} from "@/features/chats/chatApi";
import styles from "@/features/chats/chats.module.css";

export default function ChatsPage() {
  const { chats, loading: loadingChats, refresh: refreshChats } = useChatList();
  const { folders, refresh: refreshFolders } = useChatFolders();
  const modelOptions = useModelOptions();
  const { skills, refresh: refreshSkills } = useSkillsForMention();
  const { push } = useToast();

  const [selectedChatId, setSelectedChatId] = useState<string | null>(null);
  const [sidebarCollapsed, setSidebarCollapsed] = useState(false);
  const [drawerOpen, setDrawerOpen] = useState(false);

  // Dialogs
  const [showNewChatDialog, setShowNewChatDialog] = useState(false);
  const [showSpawnDialog, setShowSpawnDialog] = useState(false);
  const [showPromoteDialog, setShowPromoteDialog] = useState(false);
  const [newChatTitle, setNewChatTitle] = useState("");
  const [newChatFolder, setNewChatFolder] = useState("");
  const [spawnGoal, setSpawnGoal] = useState("");
  const [promoteProjectId, setPromoteProjectId] = useState("");
  const [promoteNewTitle, setPromoteNewTitle] = useState("");
  const [dialogLoading, setDialogLoading] = useState(false);

  // Listen for board.updated to refresh the list
  useChatRefreshSignal(refreshChats);

  // Resolve the selected chat from the list
  const selectedChat = useMemo(
    () => chats.find((c) => c.id === selectedChatId) ?? null,
    [chats, selectedChatId],
  );

  // Keyboard shortcut: Cmd+N to create new chat (global, even when sidebar is collapsed)
  useEffect(() => {
    const handler = (e: KeyboardEvent) => {
      if ((e.metaKey || e.ctrlKey) && e.key === "n") {
        e.preventDefault();
        setShowNewChatDialog(true);
      }
    };
    document.addEventListener("keydown", handler);
    return () => document.removeEventListener("keydown", handler);
  }, []);

  // When a new chat is created via Cmd+N in the sidebar, it calls onCreateChat
  // which opens the dialog (already done above via the handler on the sidebar)

  // ── Create chat ──

  const handleCreateChat = useCallback(async () => {
    setDialogLoading(true);
    try {
      const chat = await apiCreateChat({
        title: newChatTitle.trim() || "New Chat",
        folder: newChatFolder.trim() || null,
      });
      await refreshChats();
      setSelectedChatId(chat.id);
      setShowNewChatDialog(false);
      setNewChatTitle("");
      setNewChatFolder("");
      push({ tone: "success", title: "Chat created", message: chat.title });
    } catch (err) {
      push({
        tone: "error",
        title: "Could not create chat",
        message: err instanceof Error ? err.message : "Unknown error",
      });
    } finally {
      setDialogLoading(false);
    }
  }, [newChatTitle, newChatFolder, refreshChats, push]);

  // ── Move chat (drag & drop) ──

  const handleMoveChat = useCallback(
    async (chatId: string, folder: string | null) => {
      try {
        await apiUpdateChat(chatId, { folder });
        await refreshChats();
      } catch (err) {
        push({
          tone: "error",
          title: "Could not move chat",
          message: err instanceof Error ? err.message : "Unknown error",
        });
      }
    },
    [refreshChats, push],
  );

  // ── Rename chat ──

  const handleRenameChat = useCallback(
    async (chatId: string, title: string) => {
      try {
        await apiUpdateChat(chatId, { title });
        await refreshChats();
      } catch (err) {
        push({
          tone: "error",
          title: "Could not rename chat",
          message: err instanceof Error ? err.message : "Unknown error",
        });
      }
    },
    [refreshChats, push],
  );

  // ── Delete chat ──

  const handleDeleteChat = useCallback(
    async (chatId: string) => {
      try {
        await apiDeleteChat(chatId);
        if (selectedChatId === chatId) setSelectedChatId(null);
        await refreshChats();
        push({ tone: "success", message: "Chat deleted" });
      } catch (err) {
        push({
          tone: "error",
          title: "Could not delete chat",
          message: err instanceof Error ? err.message : "Unknown error",
        });
      }
    },
    [selectedChatId, refreshChats, push],
  );

  // ── Spawn (Fan out) ──

  const handleSpawn = useCallback(async () => {
    if (!selectedChatId || !spawnGoal.trim()) return;
    setDialogLoading(true);
    try {
      const result = await spawnChat(selectedChatId, spawnGoal.trim());
      push({
        tone: "success",
        title: "Agents spawned",
        message: `${result.task_ids.length} sub-task(s) created under the companion card.`,
      });
      setShowSpawnDialog(false);
      setSpawnGoal("");
    } catch (err) {
      push({
        tone: "error",
        title: "Could not spawn",
        message: err instanceof Error ? err.message : "Unknown error",
      });
    } finally {
      setDialogLoading(false);
    }
  }, [selectedChatId, spawnGoal, push]);

  // ── Promote to Board ──

  const handlePromote = useCallback(async () => {
    if (!selectedChatId) return;
    setDialogLoading(true);
    try {
      const result = await promoteChat(
        selectedChatId,
        promoteProjectId || null,
        promoteNewTitle || undefined,
      );
      push({
        tone: "success",
        title: "Promoted to Board",
        message: `${result.task_ids.length} task(s) created. View on /board.`,
      });
      setShowPromoteDialog(false);
      setPromoteProjectId("");
      setPromoteNewTitle("");
      await refreshChats();
    } catch (err) {
      push({
        tone: "error",
        title: "Could not promote",
        message: err instanceof Error ? err.message : "Unknown error",
      });
    } finally {
      setDialogLoading(false);
    }
  }, [selectedChatId, promoteProjectId, promoteNewTitle, refreshChats, push]);

  // ── Archive ──

  const handleArchive = useCallback(async () => {
    if (!selectedChatId) return;
    try {
      await apiUpdateChat(selectedChatId, { status: "archived" });
      await refreshChats();
      push({ tone: "success", message: "Chat archived" });
    } catch (err) {
      push({
        tone: "error",
        title: "Could not archive",
        message: err instanceof Error ? err.message : "Unknown error",
      });
    }
  }, [selectedChatId, refreshChats, push]);

  // ── Header actions routed to dialogs ──

  const headerTitleChange = useCallback(
    async (title: string) => {
      if (!selectedChatId) return;
      try {
        await apiUpdateChat(selectedChatId, { title });
        await refreshChats();
      } catch {
        /* silent */
      }
    },
    [selectedChatId, refreshChats],
  );

  const headerModelChange = useCallback(
    async (model: string | null) => {
      if (!selectedChatId) return;
      try {
        await apiUpdateChat(selectedChatId, { model });
        await refreshChats();
      } catch {
        /* silent */
      }
    },
    [selectedChatId, refreshChats],
  );

  // Folder options for dialogs
  const folderOptions = useMemo(
    () => [
      { value: "", label: "No folder (Inbox)" },
      ...folders.map((f) => ({ value: f, label: f })),
    ],
    [folders],
  );

  return (
    <Page>
      <PageHeader title="Chats" lead="Talk to your agents — promote to kanban when ready." />

      <div className={styles.container}>
        {/* ── Sidebar ── */}
        <ChatSidebar
          chats={chats}
          folders={folders}
          selectedChatId={selectedChatId}
          loading={loadingChats}
          collapsed={sidebarCollapsed}
          onSelectChat={setSelectedChatId}
          onCreateChat={() => setShowNewChatDialog(true)}
          onMoveChat={handleMoveChat}
          onToggleCollapse={() => setSidebarCollapsed((prev) => !prev)}
          onRenameChat={handleRenameChat}
          onDeleteChat={handleDeleteChat}
        />

        {/* ── Main area ── */}
        <div className={styles.mainArea}>
          {/* Toolbar for collapsed sidebar toggle */}
          {sidebarCollapsed && (
            <div className={styles.mainToolbar}>
              <Button
                variant="ghost"
                size="sm"
                onClick={() => setSidebarCollapsed(false)}
                title="Show sidebar"
              >
                <Icon name="menu" size={14} />
              </Button>
            </div>
          )}

          {/* Chat header + thread */}
          {selectedChat ? (
            <>
              <ChatHeader
                chat={selectedChat}
                modelOptions={modelOptions}
                onTitleChange={headerTitleChange}
                onModelChange={headerModelChange}
                onSpawn={() => setShowSpawnDialog(true)}
                onPromote={() => setShowPromoteDialog(true)}
                onArchive={handleArchive}
                onDelete={() => handleDeleteChat(selectedChat.id)}
                onToggleDrawer={() => setDrawerOpen((prev) => !prev)}
                drawerOpen={drawerOpen}
              />
              <ChatThread
                chatId={selectedChat.id}
                skills={skills}
                modelOptions={modelOptions}
                onSpawn={() => setShowSpawnDialog(true)}
                onPromote={() => setShowPromoteDialog(true)}
              />
            </>
          ) : (
            <EmptyState
              title="No chat selected"
              message="Select a chat from the sidebar or press ⌘N to start a new conversation."
            />
          )}
        </div>

        {/* ── Right drawer: workspace ── */}
        <aside
          className={`${styles.drawer}${!drawerOpen ? ` ${styles.drawerCollapsed}` : ""}`}
        >
          {drawerOpen && selectedChat && (
            <>
              <div className={styles.drawerHeader}>
                <h3 className={styles.drawerTitle}>Workspace</h3>
                <Button
                  variant="ghost"
                  size="sm"
                  onClick={() => setDrawerOpen(false)}
                  title="Close workspace"
                >
                  <Icon name="close" size={14} />
                </Button>
              </div>
              <div className={styles.drawerContent}>
                <WorkspaceTabs
                  taskId={
                    selectedChat.board_task_id ?? null
                  }
                  projectId={selectedChat.project_id ?? null}
                  projectName={null}
                />
              </div>
            </>
          )}
        </aside>
      </div>

      {/* ── Dialogs ── */}

      {/* New Chat dialog */}
      <Dialog
        open={showNewChatDialog}
        onClose={() => {
          setShowNewChatDialog(false);
          setNewChatTitle("");
          setNewChatFolder("");
        }}
        title="New Chat"
        footer={
          <>
            <Button
              variant="ghost"
              onClick={() => setShowNewChatDialog(false)}
            >
              Cancel
            </Button>
            <Button
              variant="primary"
              onClick={() => void handleCreateChat()}
              disabled={dialogLoading}
            >
              {dialogLoading ? "Creating…" : "Create"}
            </Button>
          </>
        }
      >
        <div className={styles.dialogField}>
          <label className={styles.dialogLabel}>Title (optional)</label>
          <input
            className={styles.dialogInput}
            value={newChatTitle}
            onChange={(e) => setNewChatTitle(e.target.value)}
            placeholder="New Chat"
            onKeyDown={(e) => {
              if (e.key === "Enter") void handleCreateChat();
            }}
            autoFocus
          />
        </div>
        <div className={styles.dialogField}>
          <label className={styles.dialogLabel}>Folder</label>
          <div className={styles.dialogSelectWrap}>
            <Select
              aria-label="Folder"
              value={newChatFolder}
              onChange={(val) => setNewChatFolder(val)}
              options={folderOptions}
            />
          </div>
        </div>
      </Dialog>

      {/* Spawn (Fan out) dialog */}
      <Dialog
        open={showSpawnDialog}
        onClose={() => {
          setShowSpawnDialog(false);
          setSpawnGoal("");
        }}
        title="Fan Out — Spawn Sub-Agents"
        footer={
          <>
            <Button
              variant="ghost"
              onClick={() => setShowSpawnDialog(false)}
            >
              Cancel
            </Button>
            <Button
              variant="primary"
              onClick={() => void handleSpawn()}
              disabled={dialogLoading || !spawnGoal.trim()}
            >
              {dialogLoading ? "Spawning…" : "Spawn"}
            </Button>
          </>
        }
      >
        <p className={styles.dialogHelp}>
          Describe the goal for the sub-agents. They will be created as
          children of this chat&apos;s companion task, keeping your board
          clean.
        </p>
        <div className={styles.dialogField}>
          <label className={styles.dialogLabel}>Goal</label>
          <textarea
            className={styles.dialogTextarea}
            value={spawnGoal}
            onChange={(e) => setSpawnGoal(e.target.value)}
            placeholder="e.g. Research the top 5 competitor APIs and summarize findings"
            rows={3}
            autoFocus
          />
        </div>
      </Dialog>

      {/* Promote to Board dialog */}
      <Dialog
        open={showPromoteDialog}
        onClose={() => {
          setShowPromoteDialog(false);
          setPromoteProjectId("");
          setPromoteNewTitle("");
        }}
        title="Promote to Board"
        footer={
          <>
            <Button
              variant="ghost"
              onClick={() => setShowPromoteDialog(false)}
            >
              Cancel
            </Button>
            <Button
              variant="primary"
              onClick={() => void handlePromote()}
              disabled={dialogLoading}
            >
              {dialogLoading ? "Promoting…" : "Promote"}
            </Button>
          </>
        }
      >
        <p className={styles.dialogHelp}>
          Promote this chat to the kanban board. The system extracts action
          items from the conversation and creates board tasks under a
          companion card. Link to an existing project or create a new one.
        </p>
        <div className={styles.dialogField}>
          <label className={styles.dialogLabel}>Existing project (optional)</label>
          <input
            className={styles.dialogInput}
            value={promoteProjectId}
            onChange={(e) => setPromoteProjectId(e.target.value)}
            placeholder="Project ID (leave empty for new)"
          />
        </div>
        <div className={styles.dialogField}>
          <label className={styles.dialogLabel}>New project title (optional)</label>
          <input
            className={styles.dialogInput}
            value={promoteNewTitle}
            onChange={(e) => setPromoteNewTitle(e.target.value)}
            placeholder="e.g. API Layer Redesign"
          />
        </div>
      </Dialog>
    </Page>
  );
}

/**
 * Chat API client — talks to the S1 chat backend with NEXT_PUBLIC_USE_CHATS_FIXTURES
 * fallback. Reads and mutations both go same-origin through the Next.js proxy
 * (SEC-005 convention, same as hierarchy.ts and collab/client.ts).
 *
 * Pinned contracts consumed (FINAL-PLAN.md §B):
 *   GET  /api/chats                   -> Chat[]
 *   GET  /api/chats/folders           -> { folders: string[] }
 *   POST /api/chats                   -> Chat
 *   GET  /api/chats/{id}              -> Chat
 *   PATCH /api/chats/{id}             -> Chat
 *   DELETE /api/chats/{id}            -> { ok: true }
 *   GET  /api/chats/{id}/messages     -> ChatMessage[]
 *   POST /api/chats/{id}/messages     -> ChatMessage
 *   POST /api/chats/{id}/spawn        -> { task_ids: string[] }
 *   POST /api/chats/{id}/promote      -> { project_id: string, task_ids: string[] }
 *   GET  /api/models                  -> { models: ModelEntry[] }
 *   GET  /api/skills/tree             -> SkillTreeEntry[]
 *   POST /api/board/{task_id}/files/upload -> { saved: [...] }
 */

import { fetchWithTimeout } from "@/lib/fetchTimeout";

export const USE_CHAT_FIXTURES =
  process.env.NEXT_PUBLIC_USE_CHATS_FIXTURES === "true";

// ── Types ─────────────────────────────────────────────────────

export type ChatStatus = "active" | "archived" | "promoted" | "deleted";
export type ChatScope = "chat" | "project" | "task";

export interface Chat {
  id: string;
  title: string;
  status: ChatStatus;
  project_id: string | null;
  board_task_id: string | null;
  folder: string | null;
  preferred_model: string | null;
  promoted_at: string | null;
  created_at: string;
  updated_at: string;
  message_count?: number;
}

export interface ChatCreateRequest {
  title?: string;
  project_id?: string | null;
  folder?: string | null;
  model?: string | null;
}

export interface ChatMessage {
  id: string;
  seq: number;
  role: "user" | "agent" | "system";
  content: string;
  model: string | null;
  created_at: string;
  meta_json?: string;
}

export interface ChatSendRequest {
  role: "user";
  content: string;
  model?: string | null;
  meta_json?: string;
}

export interface ModelEntry {
  id: string;
  label: string;
  provider: string;
  tier: number | null;
  available: boolean;
  lineage: string | null;
}

export interface SpawnResponse {
  task_ids: string[];
}

export interface PromoteResponse {
  project_id: string;
  task_ids: string[];
}

export interface Attachment {
  kind: "skill" | "file" | "url";
  ref: string;
  label: string;
}

export interface ChatTurnEvent {
  type:
    | "chat.turn.started"
    | "chat.turn.delta"
    | "chat.turn.completed";
  chat_id: string;
  task_id: string;
  turn: number;
  text?: string;
  model?: string;
  ts: string;
}

export interface SkillTreeEntry {
  id: string;
  name: string;
  version: string;
  path: string;
  description?: string | null;
}

// ── Error ─────────────────────────────────────────────────────

export class ChatApiError extends Error {
  constructor(
    message: string,
    readonly status: number,
  ) {
    super(message);
    this.name = "ChatApiError";
  }
}

// ── Fetch helpers ─────────────────────────────────────────────

async function fetchJson<T>(path: string, init?: RequestInit): Promise<T> {
  const isForm = init?.body instanceof FormData;
  const res = await fetchWithTimeout(path, {
    ...init,
    headers: isForm
      ? { ...(init?.headers ?? {}) }
      : { "Content-Type": "application/json", ...(init?.headers ?? {}) },
    cache: "no-store",
  });
  if (!res.ok) {
    let detail = res.statusText;
    try {
      const body = (await res.json()) as { error?: { message?: string } };
      detail = body?.error?.message ?? detail;
    } catch {
      /* keep statusText */
    }
    throw new ChatApiError(detail, res.status);
  }
  return (await res.json()) as T;
}

async function mutate<T>(
  path: string,
  init?: RequestInit,
): Promise<T> {
  return fetchJson<T>(path, init);
}

