let fixtureSeq = 100;

function fixtureMsg(
  chatId: string,
  role: ChatMessage["role"],
  content: string,
  model: string | null,
  meta?: string,
): ChatMessage {
  fixtureSeq += 1;
  return {
    id: `fxmsg_${fixtureSeq}`,
    seq: fixtureSeq,
    role,
    content,
    model,
    created_at: new Date().toISOString(),
    meta_json: meta ?? "{}",
  };
}

// ── Public API ────────────────────────────────────────────────

export async function listChats(folder?: string | null): Promise<Chat[]> {
  if (USE_CHAT_FIXTURES) {
    const list = FIXTURE_CHATS.filter((c) => c.status !== "deleted");
    if (folder === "") return list.filter((c) => !c.folder);
    if (folder) return list.filter((c) => c.folder === folder);
    return list;
  }
  const qs = folder !== undefined && folder !== null
    ? `?folder=${enc(folder)}`
    : "";
  return fetchJson<Chat[]>(`/api/chats${qs}`);
}

export async function listFolders(): Promise<string[]> {
  if (USE_CHAT_FIXTURES) return [...FIXTURE_FOLDERS];
  const data = await fetchJson<{ folders: string[] }>(
    "/api/chats/folders",
  );
  return data.folders;
}

export async function createChat(
  req: ChatCreateRequest,
): Promise<Chat> {
  if (USE_CHAT_FIXTURES) {
    fixtureSeq += 1;
    const chat: Chat = {
      id: `fxchat_${fixtureSeq}`,
      title: req.title ?? "New Chat",
      status: "active",
      project_id: req.project_id ?? null,
      board_task_id: null,
      folder: req.folder ?? null,
      preferred_model: req.model ?? null,
      promoted_at: null,
      created_at: new Date().toISOString(),
      updated_at: new Date().toISOString(),
      message_count: 0,
    };
    FIXTURE_CHATS.push(chat);
    return chat;
  }
  return mutate<Chat>("/api/chats", {
    method: "POST",
    body: JSON.stringify(req),
  });
}

export async function getChat(chatId: string): Promise<Chat> {
  if (USE_CHAT_FIXTURES) {
    const chat = FIXTURE_CHATS.find((c) => c.id === chatId);
    if (!chat) throw new ChatApiError("Chat not found", 404);
    return chat;
  }
  return fetchJson<Chat>(`/api/chats/${enc(chatId)}`);
}

export async function updateChat(
  chatId: string,
  patch: {
    title?: string;
    folder?: string | null;
    model?: string | null;
    status?: ChatStatus;
  },
): Promise<Chat> {
  if (USE_CHAT_FIXTURES) {
    const idx = FIXTURE_CHATS.findIndex((c) => c.id === chatId);
    if (idx < 0) throw new ChatApiError("Chat not found", 404);
    FIXTURE_CHATS[idx] = {
      ...FIXTURE_CHATS[idx],
      ...patch,
      preferred_model:
        patch.model !== undefined
          ? patch.model
          : FIXTURE_CHATS[idx].preferred_model,
      updated_at: new Date().toISOString(),
    };
    return FIXTURE_CHATS[idx];
  }
  return mutate<Chat>(`/api/chats/${enc(chatId)}`, {
    method: "PATCH",
    body: JSON.stringify(patch),
  });
}

export async function deleteChat(chatId: string): Promise<void> {
  if (USE_CHAT_FIXTURES) {
    const idx = FIXTURE_CHATS.findIndex((c) => c.id === chatId);
    if (idx >= 0) FIXTURE_CHATS[idx] = { ...FIXTURE_CHATS[idx], status: "deleted" };
    return;
  }
  await mutate<{ ok: boolean }>(`/api/chats/${enc(chatId)}`, {
    method: "DELETE",
  });
}

export async function listMessages(
  chatId: string,
): Promise<ChatMessage[]> {
  if (USE_CHAT_FIXTURES) {
    return [...(FIXTURE_MESSAGES[chatId] ?? [])];
  }
  return fetchJson<ChatMessage[]>(
    `/api/chats/${enc(chatId)}/messages`,
  );
}

export async function sendMessage(
  chatId: string,
  req: ChatSendRequest,
): Promise<ChatMessage> {
  if (USE_CHAT_FIXTURES) {
    const msg = fixtureMsg(
      chatId,
      req.role,
      req.content,
      req.model ?? null,
      req.meta_json,
    );
    (FIXTURE_MESSAGES[chatId] ??= []).push(msg);
    return msg;
  }
  return mutate<ChatMessage>(`/api/chats/${enc(chatId)}/messages`, {
    method: "POST",
    body: JSON.stringify(req),
  });
}

export async function spawnChat(
  chatId: string,
  goal: string,
  count?: number,
): Promise<SpawnResponse> {
  if (USE_CHAT_FIXTURES) {
    return {
      task_ids: Array.from(
        { length: count ?? 2 },
        (_, i) => `fxspawn_${Date.now()}_${i}`,
      ),
    };
  }
  return mutate<SpawnResponse>(
    `/api/chats/${enc(chatId)}/spawn`,
    {
      method: "POST",
      body: JSON.stringify({ goal, count }),
    },
  );
}

export async function promoteChat(
  chatId: string,
  projectId: string | null,
  newProjectTitle?: string,
): Promise<PromoteResponse> {
  if (USE_CHAT_FIXTURES) {
    return {
      project_id:
        projectId ?? `fxprj_${Date.now()}`,
      task_ids: [
        `fxtask_${Date.now()}_1`,
        `fxtask_${Date.now()}_2`,
      ],
    };
  }
  return mutate<PromoteResponse>(
    `/api/chats/${enc(chatId)}/promote`,
    {
      method: "POST",
      body: JSON.stringify({
        project_id: projectId,
        new_project_title: newProjectTitle,
      }),
    },
  );
}

export async function fetchModels(): Promise<ModelEntry[]> {
  if (USE_CHAT_FIXTURES) return [...FIXTURE_MODELS];
  const data = await fetchJson<{ models: ModelEntry[] }>(
    "/api/models",
  );
  return data.models;
}

export async function fetchSkillsTree(): Promise<SkillTreeEntry[]> {
  if (USE_CHAT_FIXTURES) return [...FIXTURE_SKILLS];
  return fetchJson<SkillTreeEntry[]>("/api/skills/tree");
}

export async function uploadChatFile(
  taskId: string,
  files: File[],
): Promise<{
  saved: Array<{ name: string; size: number; path: string }>;
  workspace: string | null;
}> {
  const formData = new FormData();
  files.forEach((f) => formData.append("files", f));
  if (USE_CHAT_FIXTURES) {
    return {
      saved: files.map((f) => ({
        name: f.name,
        size: f.size,
        path: `uploads/${f.name}`,
      })),
      workspace: null,
    };
  }
  return fetchJson(
    `/api/board/${enc(taskId)}/files/upload`,
    { method: "POST", body: formData },
  );
}

"use client";

/**
 * React hooks for the Chat feature (S3 frontend).
 *
 * Every hook consumes the chatApi client and follows the project's fixture
 * convention: when NEXT_PUBLIC_USE_CHATS_FIXTURES=true (or the API is
 * unreachable), the hook falls back to in-memory fixture data so the page
 * always renders. `source` lets the UI show a "demo data" notice.
 *
 * Hooks:
 *   useModelOptions  — replaces the hardcoded 5-entry list in hierarchyHooks
 *   useChatList      — chat list with optional folder filter
 *   useChatFolders   — folder name list
 *   useChatThread    — messages + streaming + CRUD for one chat
 *   useSkillsForMention — skill tree for @mention autocomplete
 */

import {
  useCallback,
  useEffect,
  useRef,
  useState,
} from "react";
import {
  USE_CHAT_FIXTURES,
  type Chat,
  type ChatMessage,
  type ChatStatus,
  type ChatTurnEvent,
  type ModelEntry,
  type SkillTreeEntry,
  type SpawnResponse,
  type PromoteResponse,
  type Attachment,
} from "./chatApi";
import * as chatApi from "./chatApi";
import { useEventChannel } from "@/lib/useEventChannel";

export type DataSource = "live" | "fixtures";

function errText(reason: unknown, fallback: string): string {
  return reason instanceof Error ? reason.message : fallback;
}

// ── useModelOptions ───────────────────────────────────────────

const FALLBACK_MODELS = [
  { value: "", label: "Auto — router decides" },
];

export function useModelOptions(): Array<{
  value: string;
  label: string;
}> {
  const [options, setOptions] = useState(FALLBACK_MODELS);

  useEffect(() => {
    let cancelled = false;
    chatApi
      .fetchModels()
      .then((models) => {
        if (cancelled) return;
        setOptions(
          models.map((m) => ({
            value: m.id,
            label: m.available ? m.label : `${m.label} (unavailable)`,
          })),
        );
      })
      .catch(() => {
        /* keep fallback */
      });
    return () => {
      cancelled = true;
    };
  }, []);

  return options;
}

// ── useChatList ───────────────────────────────────────────────

interface ChatListState {
  chats: Chat[];
  loading: boolean;
  error: string | null;
  source: DataSource;
}

export type ChatListActions = {
  refresh: () => Promise<void>;
};

export function useChatList(folder?: string | null): ChatListState & ChatListActions {
  const [state, setState] = useState<ChatListState>({
    chats: [],
    loading: true,
    error: null,
    source: "live",
  });

  const refresh = useCallback(async () => {
    setState((prev) => ({ ...prev, loading: true }));
    try {
      const chats = await chatApi.listChats(folder);
      setState({
        chats,
        loading: false,
        error: null,
        source: USE_CHAT_FIXTURES ? "fixtures" : "live",
      });
    } catch (reason) {
      setState((prev) => ({
        ...prev,
        loading: false,
        error: errText(reason, "Could not load chats"),
        source: "fixtures",
      }));
    }
  }, [folder]);

  useEffect(() => {
    void refresh();
  }, [refresh]);

  return { ...state, refresh };
}

// ── useChatFolders ────────────────────────────────────────────

export function useChatFolders() {
  const [folders, setFolders] = useState<string[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const refresh = useCallback(async () => {
    setLoading(true);
    try {
      const result = await chatApi.listFolders();
      setFolders(result);
      setError(null);
    } catch (reason) {
      setError(errText(reason, "Could not load folders"));
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    void refresh();
  }, [refresh]);

  return { folders, loading, error, refresh };
}

// ── useChatThread ─────────────────────────────────────────────

export type TurnState = "idle" | "queued" | "running" | "completed";

interface ThreadState {
  chat: Chat | null;
  messages: ChatMessage[];
  loading: boolean;
  error: string | null;
  source: DataSource;
  sending: boolean;
  turnState: TurnState;
  streamingText: string;
  streamingModel: string | null;
  streamingTurn: number | null;
}

export type ThreadActions = {
  refresh: () => Promise<void>;
  append: (
    content: string,
    model?: string | null,
    attachments?: Attachment[],
  ) => Promise<void>;
  spawn: (goal: string, count?: number) => Promise<SpawnResponse>;
  promote: (
    projectId: string | null,
    newProjectTitle?: string,
  ) => Promise<PromoteResponse>;
  archive: () => Promise<void>;
  deleteChat: () => Promise<void>;
  updateTitle: (title: string) => Promise<void>;
  updateFolder: (folder: string | null) => Promise<void>;
  updateModel: (model: string | null) => Promise<void>;
  uploadFiles: (files: File[]) => Promise<Array<{ name: string; path: string }>>;
};

export function useChatThread(
  chatId: string | null,
): ThreadState & ThreadActions {
  const [state, setState] = useState<ThreadState>({
    chat: null,
    messages: [],
    loading: false,
    error: null,
    source: "live",
    sending: false,
    turnState: "idle",
    streamingText: "",
    streamingModel: null,
    streamingTurn: null,
  });

  const streamBuf = useRef("");
  const streamModel = useRef<string | null>(null);
  const streamTurn = useRef<number | null>(null);

  // ── Load chat + messages when chatId changes ──

  const refresh = useCallback(async () => {
    if (!chatId) return;
    setState((prev) => ({ ...prev, loading: true }));
    try {
      const [chat, messages] = await Promise.all([
        chatApi.getChat(chatId),
        chatApi.listMessages(chatId),
      ]);
      setState({
        chat,
        messages,
        loading: false,
        error: null,
        source: USE_CHAT_FIXTURES ? "fixtures" : "live",
        sending: false,
        turnState: "idle",
        streamingText: "",
        streamingModel: null,
        streamingTurn: null,
      });
    } catch (reason) {
      setState((prev) => ({
        ...prev,
        loading: false,
        error: errText(reason, "Could not load the chat"),
        source: "fixtures",
      }));
    }
  }, [chatId]);

  useEffect(() => {
    void refresh();
  }, [refresh]);

  // ── SSE streaming via useEventChannel ──

  const { lastEvent } = useEventChannel([
    "chat.turn.started" as string,
    "chat.turn.delta" as string,
    "chat.turn.completed" as string,
  ]);

  useEffect(() => {
    if (!lastEvent || !chatId) return;
    const evt = lastEvent.payload as unknown as ChatTurnEvent | undefined;
    if (!evt) return;
    const type = lastEvent.type as string;
    const evtChatId =
      (typeof evt.chat_id === "string" && evt.chat_id) ||
      (lastEvent.target_id === chatId ? chatId : "");
    if (evtChatId !== chatId) return;

    if (type === "chat.turn.started") {
      streamBuf.current = "";
      streamModel.current = (typeof evt.model === "string" && evt.model) || null;
      streamTurn.current = typeof evt.turn === "number" ? evt.turn : null;
      setState((prev) => ({
        ...prev,
        turnState: "running",
        streamingText: "",
        streamingModel: streamModel.current,
        streamingTurn: streamTurn.current,
      }));
    } else if (type === "chat.turn.delta") {
      const delta = typeof evt.text === "string" ? evt.text : "";
      streamBuf.current += delta;
      setState((prev) => ({
        ...prev,
        streamingText: streamBuf.current,
        streamingModel: streamModel.current ?? prev.streamingModel,
      }));
    } else if (type === "chat.turn.completed") {
      const finalText = streamBuf.current;
      const model = streamModel.current;
      const turn = streamTurn.current;
      streamBuf.current = "";
      streamModel.current = null;
      streamTurn.current = null;
      // Append the completed agent message to the list.
      const agentMsg: ChatMessage = {
        id: `sse_${chatId}_${turn ?? Date.now()}`,
        seq: turn ?? -1,
        role: "agent",
        content: finalText || (typeof evt.text === "string" ? evt.text : ""),
        model: (typeof evt.model === "string" && evt.model) || model,
        created_at: evt.ts || new Date().toISOString(),
        meta_json: "{}",
      };
      setState((prev) => ({
        ...prev,
        turnState: "completed",
        streamingText: "",
        streamingModel: null,
        streamingTurn: null,
        messages: deduplicateMessages([...prev.messages, agentMsg]),
      }));
    }
  }, [lastEvent, chatId]);

  // ── Actions ──

  const append = useCallback(
    async (
      content: string,
      model?: string | null,
      attachments?: Attachment[],
    ) => {
      if (!chatId || !content.trim()) return;
      setState((prev) => ({ ...prev, sending: true, turnState: "queued" }));
      try {
        const meta =
          attachments && attachments.length > 0
            ? JSON.stringify({ attachments })
            : undefined;
        const msg = await chatApi.sendMessage(chatId, {
          role: "user",
          content: content.trim(),
          model: model ?? undefined,
          meta_json: meta,
        });
        setState((prev) => ({
          ...prev,
          sending: false,
          messages: deduplicateMessages([...prev.messages, msg]),
        }));
      } catch (reason) {
        setState((prev) => ({
          ...prev,
          sending: false,
          error: errText(reason, "Could not send message"),
        }));
        throw reason;
      }
    },
    [chatId],
  );

  const spawn = useCallback(
    async (goal: string, count?: number): Promise<SpawnResponse> => {
      if (!chatId) return { task_ids: [] };
      return chatApi.spawnChat(chatId, goal, count);
    },
    [chatId],
  );

  const promote = useCallback(
    async (
      projectId: string | null,
      newProjectTitle?: string,
    ): Promise<PromoteResponse> => {
      if (!chatId) return { project_id: "", task_ids: [] };
      const result = await chatApi.promoteChat(
        chatId,
        projectId,
        newProjectTitle,
      );
      await refresh();
      return result;
    },
    [chatId, refresh],
  );

  const archive = useCallback(async () => {
    if (!chatId) return;
    await chatApi.updateChat(chatId, { status: "archived" });
    await refresh();
  }, [chatId, refresh]);

  const deleteChat = useCallback(async () => {
    if (!chatId) return;
    await chatApi.deleteChat(chatId);
    await refresh();
  }, [chatId, refresh]);

  const updateTitle = useCallback(
    async (title: string) => {
      if (!chatId) return;
      await chatApi.updateChat(chatId, { title });
      setState((prev) =>
        prev.chat ? { ...prev, chat: { ...prev.chat, title } } : prev,
      );
    },
    [chatId],
  );

  const updateFolder = useCallback(
    async (folder: string | null) => {
      if (!chatId) return;
      await chatApi.updateChat(chatId, { folder });
      setState((prev) =>
        prev.chat ? { ...prev, chat: { ...prev.chat, folder } } : prev,
      );
    },
    [chatId],
  );

  const updateModel = useCallback(
    async (model: string | null) => {
      if (!chatId) return;
      await chatApi.updateChat(chatId, { model });
      setState((prev) =>
        prev.chat
          ? { ...prev, chat: { ...prev.chat, preferred_model: model } }
          : prev,
      );
    },
    [chatId],
  );

  const uploadFiles = useCallback(
    async (
      files: File[],
    ): Promise<Array<{ name: string; path: string }>> => {
      if (!chatId || !files.length) return [];
      const taskId = state.chat?.board_task_id;
      if (!taskId) {
        throw new Error("No companion task for file uploads");
      }
      const result = await chatApi.uploadChatFile(taskId, files);
      return result.saved.map((s) => ({ name: s.name, path: s.path }));
    },
    [chatId, state.chat?.board_task_id],
  );

  return {
    ...state,
    refresh,
    append,
    spawn,
    promote,
    archive,
    deleteChat,
    updateTitle,
    updateFolder,
    updateModel,
    uploadFiles,
  };
}

// ── useSkillsForMention ───────────────────────────────────────

export function useSkillsForMention() {
  const [skills, setSkills] = useState<SkillTreeEntry[]>([]);
  const [loading, setLoading] = useState(true);

  const refresh = useCallback(async () => {
    setLoading(true);
    try {
      const result = await chatApi.fetchSkillsTree();
      setSkills(result);
    } catch {
      setSkills([]);
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    void refresh();
  }, [refresh]);

  return { skills, loading, refresh };
}

// ── Shared chat event re-fetch ────────────────────────────────

/**
 * Listen for chat.updated events on the SSE bus and call refresh when the
 * event pertains to any chat (so sidebar counts stay in sync).
 */
export function useChatRefreshSignal(refresh: () => void) {
  const { lastEvent } = useEventChannel(["board.updated" as string]);

  useEffect(() => {
    if (
      lastEvent &&
      (lastEvent.type === "board.updated" ||
        (lastEvent.target_type === "chat"))
    ) {
      void Promise.resolve(refresh());
    }
  }, [lastEvent, refresh]);
}

// ─────────────────────────────────────────────────────────────

/** Deduplicate messages by id, preferring the latest occurrence. */
function deduplicateMessages(msgs: ChatMessage[]): ChatMessage[] {
  const seen = new Map<string, ChatMessage>();
  for (const m of msgs) {
    seen.set(m.id, m);
  }
  return [...seen.values()];
}

"use client";

/**
 * ChatSidebar — folder tree + Inbox + Cmd+N new chat + drag-to-folder.
 *
 * Groups chats by folder. Folderless chats land in a special "Inbox" group.
 * Supports drag-and-drop to move chats between folders, keyboard-first new
 * chat (Cmd+N at the page level is wired in page.tsx), and rename/delete.
 */

import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { Badge, Button, EmptyState, Icon, Loading } from "@/design";
import type { Chat } from "./chatApi";
import styles from "./chats.module.css";

interface ChatSidebarProps {
  chats: Chat[];
  folders: string[];
  selectedChatId: string | null;
  loading: boolean;
  collapsed: boolean;
  onSelectChat: (chatId: string) => void;
  onCreateChat: () => void;
  onMoveChat: (chatId: string, folder: string | null) => void;
  onToggleCollapse: () => void;
  onRenameChat: (chatId: string, title: string) => void;
  onDeleteChat: (chatId: string) => void;
}

const INBOX_KEY = "__inbox__";

export function ChatSidebar({
  chats,
  folders,
  selectedChatId,
  loading,
  collapsed,
  onSelectChat,
  onCreateChat,
  onMoveChat,
  onToggleCollapse,
  onRenameChat,
  onDeleteChat,
}: ChatSidebarProps) {
  const [dropTargetFolder, setDropTargetFolder] = useState<string | null>(null);
  const [draggingChatId, setDraggingChatId] = useState<string | null>(null);
  const [contextMenu, setContextMenu] = useState<{
    chatId: string;
    x: number;
    y: number;
  } | null>(null);
  const contextMenuRef = useRef<HTMLDivElement>(null);

  // Group chats by folder
  const grouped = useMemo(() => {
    const map: Record<string, Chat[]> = {};
    for (const f of folders) map[f] = [];
    map[INBOX_KEY] = [];
    for (const chat of chats) {
      if (chat.status === "deleted") continue;
      const key = chat.folder ?? INBOX_KEY;
      if (!map[key]) map[key] = [];
      map[key].push(chat);
    }
    // Sort each group by updated_at descending
    for (const key of Object.keys(map)) {
      map[key].sort(
        (a, b) =>
          new Date(b.updated_at).getTime() -
          new Date(a.updated_at).getTime(),
      );
    }
    return map;
  }, [chats, folders]);

  // Close context menu on outside click
  useEffect(() => {
    if (!contextMenu) return;
    const handler = (e: MouseEvent) => {
      if (
        contextMenuRef.current &&
        !contextMenuRef.current.contains(e.target as Node)
      ) {
        setContextMenu(null);
      }
    };
    document.addEventListener("mousedown", handler);
    return () => document.removeEventListener("mousedown", handler);
  }, [contextMenu]);

  // ── Drag & drop ──

  const handleDragStart = useCallback(
    (e: React.DragEvent, chatId: string) => {
      setDraggingChatId(chatId);
      e.dataTransfer.setData("text/plain", chatId);
      e.dataTransfer.effectAllowed = "move";
    },
    [],
  );

  const handleDragEnd = useCallback(() => {
    setDraggingChatId(null);
    setDropTargetFolder(null);
  }, []);

  const handleDragOver = useCallback(
    (e: React.DragEvent, folder: string) => {
      e.preventDefault();
      e.dataTransfer.dropEffect = "move";
      setDropTargetFolder(folder);
    },
    [],
  );

  const handleDragLeave = useCallback(() => {
    setDropTargetFolder(null);
  }, []);

  const handleDrop = useCallback(
    (e: React.DragEvent, folder: string) => {
      e.preventDefault();
      const chatId = e.dataTransfer.getData("text/plain");
      if (chatId) {
        const folderValue = folder === INBOX_KEY ? null : folder;
        onMoveChat(chatId, folderValue);
      }
      setDropTargetFolder(null);
      setDraggingChatId(null);
    },
    [onMoveChat],
  );

  // ── Context menu ──

  const handleContextMenu = useCallback(
    (e: React.MouseEvent, chatId: string) => {
      e.preventDefault();
      setContextMenu({ chatId, x: e.clientX, y: e.clientY });
    },
    [],
  );

  // Cmd+N is handled globally at the page level — the sidebar button
  // (onCreateChat prop below) covers the keyboard-unreachable path.

  // ── Format timestamp ──

  const formatTime = (value: string): string => {
    if (!value) return "";
    const date = new Date(value);
    if (Number.isNaN(date.getTime())) return "";
    const now = new Date();
    const diffMs = now.getTime() - date.getTime();
    const diffMins = Math.floor(diffMs / 60000);
    if (diffMins < 1) return "now";
    if (diffMins < 60) return `${diffMins}m`;
    const diffHours = Math.floor(diffMins / 60);
    if (diffHours < 24) return `${diffHours}h`;
    const diffDays = Math.floor(diffHours / 24);
    if (diffDays === 1) return "yesterday";
    if (diffDays < 7) return `${diffDays}d`;
    return date.toLocaleDateString([], { month: "short", day: "numeric" });
  };

  // ── Render ──

  const sidebarClassName = `${styles.sidebar}${collapsed ? ` ${styles.sidebarCollapsed}` : ""}`;

  // Build ordered folder keys: named folders first, then Inbox
  const orderedFolders = [
    ...folders.filter((f) => (grouped[f] ?? []).length > 0),
    ...(grouped[INBOX_KEY]?.length ? [INBOX_KEY] : []),
  ];
  // Also show empty folders so users can drop into them
  for (const f of folders) {
    if (!orderedFolders.includes(f)) orderedFolders.push(f);
  }

  return (
    <aside className={sidebarClassName}>
      <div className={styles.sidebarHeader}>
        <h2 className={styles.sidebarTitle}>Chats</h2>
        <div className={styles.headerActions}>
          <Button
            variant="ghost"
            size="sm"
            onClick={onCreateChat}
            title="New chat (⌘N)"
          >
            <Icon name="plus" size={14} />
          </Button>
          <button
            className={styles.sidebarToggle}
            onClick={onToggleCollapse}
            aria-label="Collapse sidebar"
          >
            <Icon name="menu" size={14} />
          </button>
        </div>
      </div>

      <div className={styles.sidebarScroll}>
        {loading && chats.length === 0 ? (
          <Loading label="Loading chats…" />
        ) : chats.length === 0 && folders.length === 0 ? (
          <EmptyState
            title="No chats yet"
            message="Press ⌘N or click + to start a conversation."
          />
        ) : (
          orderedFolders.map((folderKey) => {
            const folderChats = grouped[folderKey] ?? [];
            const isInbox = folderKey === INBOX_KEY;
            const folderName = isInbox ? "Inbox" : folderKey;
            const isDropTarget = dropTargetFolder === folderKey;

            return (
              <div key={folderKey} className={styles.folderGroup}>
                <div
                  className={`${styles.folderLabel}${isDropTarget ? ` ${styles.folderDropTarget}` : ""}`}
                  onDragOver={(e) => handleDragOver(e, folderKey)}
                  onDragLeave={handleDragLeave}
                  onDrop={(e) => handleDrop(e, folderKey)}
                >
                  <Icon name={isInbox ? "inbox" : "grid"} size={12} />
                  <span className={styles.folderName}>{folderName}</span>
                  {folderChats.length > 0 && (
                    <span className={styles.folderCount}>
                      {folderChats.length}
                    </span>
                  )}
                </div>

                {folderChats.map((chat) => (
                  <div
                    key={chat.id}
                    className={`${styles.chatItem}${
                      chat.id === selectedChatId
                        ? ` ${styles.chatItemActive}`
                        : ""
                    }${
                      chat.id === draggingChatId
                        ? ` ${styles.chatItemDragging}`
                        : ""
                    }`}
                    draggable
                    onDragStart={(e) => handleDragStart(e, chat.id)}
                    onDragEnd={handleDragEnd}
                    onClick={() => onSelectChat(chat.id)}
                    onContextMenu={(e) => handleContextMenu(e, chat.id)}
                    role="button"
                    tabIndex={0}
                    onKeyDown={(e) => {
                      if (e.key === "Enter") onSelectChat(chat.id);
                    }}
                  >
                    <div className={styles.chatItemContent}>
                      <span className={styles.chatItemTitle}>
                        {chat.title || "Untitled"}
                      </span>
                      <span className={styles.chatItemMeta}>
                        {formatTime(chat.updated_at)}
                        {chat.preferred_model
                          ? ` · ${chat.preferred_model}`
                          : ""}
                      </span>
                    </div>
                    {chat.status === "promoted" && (
                      <Badge tone="completed" className={styles.chatItemBadge}>
                        promoted
                      </Badge>
                    )}
                    {chat.status === "archived" && (
                      <Badge tone="neutral" className={styles.chatItemBadge}>
                        archived
                      </Badge>
                    )}
                  </div>
                ))}
              </div>
            );
          })
        )}

        <button className={styles.newChatBtn} onClick={onCreateChat}>
          <Icon name="plus" size={14} />
          New Chat
        </button>
      </div>

      {/* Context menu (positioned absolutely via portal would be ideal, but
          for a sidebar-scoped menu this is sufficient). */}
      {contextMenu && (
        <div
          ref={contextMenuRef}
          className={styles.mentionPopover}
          role="menu"
          data-x={contextMenu.x}
          data-y={contextMenu.y}
        >
          <button
            className={styles.mentionItem}
            role="menuitem"
            onClick={() => {
              const input = prompt("Rename chat:");
              if (input?.trim()) onRenameChat(contextMenu.chatId, input.trim());
              setContextMenu(null);
            }}
          >
            Rename…
          </button>
          <button
            className={styles.mentionItem}
            role="menuitem"
            onClick={() => {
              onMoveChat(contextMenu.chatId, null);
              setContextMenu(null);
            }}
          >
            Move to Inbox
          </button>
          <button
            className={styles.mentionItem}
            role="menuitem"
            onClick={() => {
              if (confirm("Delete this chat?")) {
                onDeleteChat(contextMenu.chatId);
              }
              setContextMenu(null);
            }}
          >
            Delete
          </button>
        </div>
      )}
    </aside>
  );
}

"use client";

/**
 * ChatHeader — editable title, model picker, Fan out, Promote to Board,
 * archive/delete, and drawer toggle.
 */

import { useCallback, useState } from "react";
import { Badge, Button, Icon, Select } from "@/design";
import type { Chat } from "./chatApi";
import styles from "./chats.module.css";

interface ChatHeaderProps {
  chat: Chat;
  modelOptions: Array<{ value: string; label: string }>;
  onTitleChange: (title: string) => void;
  onModelChange: (model: string | null) => void;
  onSpawn: () => void;
  onPromote: () => void;
  onArchive: () => void;
  onDelete: () => void;
  onToggleDrawer: () => void;
  drawerOpen: boolean;
}

export function ChatHeader({
  chat,
  modelOptions,
  onTitleChange,
  onModelChange,
  onSpawn,
  onPromote,
  onArchive,
  onDelete,
  onToggleDrawer,
  drawerOpen,
}: ChatHeaderProps) {
  const [editingTitle, setEditingTitle] = useState(false);
  const [titleDraft, setTitleDraft] = useState(chat.title);

  const commitTitle = useCallback(() => {
    setEditingTitle(false);
    const trimmed = titleDraft.trim();
    if (trimmed && trimmed !== chat.title) {
      onTitleChange(trimmed);
    } else {
      setTitleDraft(chat.title);
    }
  }, [titleDraft, chat.title, onTitleChange]);

  const currentModel = chat.preferred_model ?? "auto";

  return (
    <div className={styles.header}>
      <div className={styles.headerTitleWrap}>
        {editingTitle ? (
          <input
            className={styles.headerTitleInput}
            value={titleDraft}
            onChange={(e) => setTitleDraft(e.target.value)}
            onBlur={commitTitle}
            onKeyDown={(e) => {
              if (e.key === "Enter") commitTitle();
              if (e.key === "Escape") {
                setTitleDraft(chat.title);
                setEditingTitle(false);
              }
            }}
            autoFocus
          />
        ) : (
          <div
            className={styles.headerTitleDisplay}
            onClick={() => {
              setTitleDraft(chat.title);
              setEditingTitle(true);
            }}
            role="button"
            tabIndex={0}
            onKeyDown={(e) => {
              if (e.key === "Enter") {
                setTitleDraft(chat.title);
                setEditingTitle(true);
              }
            }}
            title="Click to rename"
          >
            {chat.title || "Untitled Chat"}
          </div>
        )}
        <div className={styles.headerSubline}>
          {chat.board_task_id && (
            <span>task: {chat.board_task_id}</span>
          )}
          {chat.status === "promoted" && (
            <Badge tone="completed">promoted</Badge>
          )}
          {chat.status === "archived" && (
            <Badge tone="neutral">archived</Badge>
          )}
        </div>
      </div>

      <div className={styles.headerActions}>
        <div className={styles.dialogSelectWrap}>
          <Select
            aria-label="Model"
            value={currentModel}
            onChange={(val) => {
              onModelChange(val === "auto" ? null : val);
            }}
            options={modelOptions}
          />
        </div>

        <div className={styles.headerDivider} />

        <Button
          variant="ghost"
          size="sm"
          onClick={onSpawn}
          title="Fan out — spawn sub-agents"
        >
          <Icon name="sparkles" size={14} />
          Fan&nbsp;out
        </Button>

        <Button
          variant="secondary"
          size="sm"
          onClick={onPromote}
          title="Promote to Board"
          disabled={chat.status === "promoted"}
        >
          <Icon name="columns" size={14} />
          Promote
        </Button>

        <div className={styles.headerDivider} />

        <Button
          variant="ghost"
          size="sm"
          onClick={onArchive}
          title="Archive"
          disabled={chat.status === "archived" || chat.status === "deleted"}
        >
          Archive
        </Button>

        <Button
          variant="ghost"
          size="sm"
          onClick={onDelete}
          title="Delete chat"
        >
          <Icon name="close" size={14} />
        </Button>

        <Button
          variant="ghost"
          size="sm"
          onClick={onToggleDrawer}
          title={drawerOpen ? "Hide workspace" : "Show workspace"}
        >
          <Icon name={drawerOpen ? "chevronRight" : "columns"} size={14} />
        </Button>
      </div>
    </div>
  );
}

"use client";

/**
 * ChatThread — scope-aware (chat | project | task) single-conversation
 * primitive. Subscribes to chat.turn.* SSE events via the existing
 * useEventChannel. Renders streamed deltas live, tool-call cards,
 * per-turn model badges, and queued→running→done state chips.
 *
 * Agent turns (role="agent") render with accent styling to visually
 * distinguish them from user and system messages.
 */

import { useEffect, useMemo, useRef } from "react";
import { Badge, EmptyState, ErrorState, Loading } from "@/design";
import type { ChatMessage, Attachment } from "./chatApi";
import { ChatComposer } from "./ChatComposer";
import type { SkillTreeEntry, ModelEntry } from "./chatApi";
import { useChatThread, type TurnState } from "./useChats";
import styles from "./chats.module.css";

interface ChatThreadProps {
  chatId: string | null;
  skills: SkillTreeEntry[];
  modelOptions: Array<{ value: string; label: string }>;
  onSpawn: () => void;
  onPromote: () => void;
}

const roleMeta: Record<
  string,
  { className: string; label: string }
> = {
  user: { className: styles.msgUser, label: "You" },
  agent: { className: styles.msgAgent, label: "Agent" },
  system: { className: styles.msgSystem, label: "System" },
};

function relTime(value: string): string {
  if (!value) return "";
  const date = new Date(value);
  return Number.isNaN(date.getTime())
    ? value
    : date.toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" });
}

function parseAttachments(metaJson?: string): Attachment[] {
  if (!metaJson) return [];
  try {
    const parsed = JSON.parse(metaJson) as Record<string, unknown>;
    const atts = parsed.attachments;
    if (Array.isArray(atts)) {
      return atts.filter(
        (a): a is Attachment =>
          typeof a === "object" &&
          a !== null &&
          "kind" in a &&
          "ref" in a &&
          "label" in a,
      );
    }
  } catch {
    /* not JSON */
  }
  return [];
}

export function ChatThread({
  chatId,
  skills,
  modelOptions,
  onSpawn,
  onPromote,
}: ChatThreadProps) {
  const {
    chat,
    messages,
    loading,
    error,
    sending,
    turnState,
    streamingText,
    streamingModel,
    refresh,
    append,
    uploadFiles,
  } = useChatThread(chatId);

  const scrollRef = useRef<HTMLDivElement>(null);

  // Auto-scroll to bottom on new messages or streaming updates
  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages, streamingText, sending]);

  const handleSend = async (
    content: string,
    model: string | null,
    attachments: Attachment[],
  ) => {
    await append(content, model, attachments);
  };

  // ── State chip ──

  const stateChip = useMemo(() => {
    if (turnState === "queued")
      return (
        <span className={`${styles.stateChip} ${styles.stateChipQueued}`}>
          queued
        </span>
      );
    if (turnState === "running")
      return (
        <span className={`${styles.stateChip} ${styles.stateChipRunning}`}>
          running…
        </span>
      );
    if (turnState === "completed")
      return (
        <span className={`${styles.stateChip} ${styles.stateChipDone}`}>
          done
        </span>
      );
    return null;
  }, [turnState]);

  if (!chatId) {
    return (
      <div className={styles.threadContainer}>
        <EmptyState
          title="No chat selected"
          message="Select a chat from the sidebar or press ⌘N to start a new one."
        />
      </div>
    );
  }

  if (error && !messages.length && !loading) {
    return (
      <div className={styles.threadContainer}>
        <ErrorState
          title="Could not load chat"
          message={error}
          onRetry={refresh}
        />
      </div>
    );
  }

  return (
    <div className={styles.threadContainer}>
      <div className={styles.threadScroll} ref={scrollRef}>
        {loading && messages.length === 0 ? (
          <div className={styles.skeletonBlock}>
            <div className="ds-skeleton" />
          </div>
        ) : messages.length === 0 && turnState === "idle" ? (
          <EmptyState
            title="No messages yet"
            message="Type a message below to start the conversation. Use @ to attach skills."
          />
        ) : (
          <>
            {messages.map((m) => (
              <MessageBubble key={m.id} message={m} />
            ))}
            {/* Streaming agent reply */}
            {turnState === "running" && streamingText && (
              <div className={`${styles.msg} ${styles.msgAgent}`}>
                <div className={styles.msgHead}>
                  <span className={styles.msgRole}>Agent</span>
                  {streamingModel && (
                    <Badge tone="neutral">{streamingModel}</Badge>
                  )}
                  {stateChip}
                </div>
                <div className={`${styles.msgBubble} ${styles.msgAgent}`}>
                  <div className={styles.msgBody}>
                    {streamingText}
                    <span className={styles.streamCursor} />
                  </div>
                </div>
              </div>
            )}
            {/* Queued indicator (no streaming text yet) */}
            {turnState === "queued" && (
              <div className={`${styles.msg} ${styles.msgSystem}`}>
                <div className={styles.msgBubble}>
                  {stateChip}
                  <span className={styles.msgBody}>
                    Message sent — waiting for agent…
                  </span>
                </div>
              </div>
            )}
          </>
        )}
      </div>

      <ChatComposer
        onSend={handleSend}
        onUploadFiles={uploadFiles}
        skills={skills}
        modelOptions={modelOptions}
        sending={sending || turnState === "running" || turnState === "queued"}
        hasBoardTask={Boolean(chat?.board_task_id)}
      />
    </div>
  );
}

// ── MessageBubble (sub-component) ────────────────────────────

function MessageBubble({ message }: { message: ChatMessage }) {
  const meta = roleMeta[message.role] ?? roleMeta.agent;
  const attachments = parseAttachments(message.meta_json);

  return (
    <div className={`${styles.msg} ${meta.className}`}>
      <div className={styles.msgHead}>
        <span className={styles.msgRole}>{meta.label}</span>
        {message.model && <Badge tone="neutral">{message.model}</Badge>}
        <span>{relTime(message.created_at)}</span>
      </div>
      <div className={styles.msgBubble}>
        <div className={styles.msgBody}>{message.content}</div>
        {/* Tool call cards: parsed from content markers */}
        <ToolCallCards content={message.content} role={message.role} />
      </div>
      {/* Attachment pills */}
      {attachments.length > 0 && (
        <div className={styles.attachmentRow}>
          {attachments.map((att, i) => (
            <span key={`${att.kind}-${att.ref}-${i}`} className={styles.attachmentPill}>
              {att.kind === "skill" ? "@" : att.kind === "file" ? "📎" : "🔗"}{" "}
              {att.label}
            </span>
          ))}
        </div>
      )}
    </div>
  );
}

// ── ToolCallCards ─────────────────────────────────────────────

/** Look for [tool:name] markers in agent content and render them as cards. */
function ToolCallCards({
  content,
  role,
}: {
  content: string;
  role: string;
}) {
  if (role !== "agent") return null;
  const matches = content.matchAll(/\[(?:tool|tool_call):([^\]]+)\]/g);
  const cards = [...matches];
  if (cards.length === 0) return null;

  return (
    <>
      {cards.map((m, i) => (
        <div key={i} className={styles.toolCallCard}>
          <span className={styles.toolCallLabel}>Tool</span>
          {m[1]}
        </div>
      ))}
    </>
  );
}

"use client";

/**
 * ChatComposer — the message input with @skill mention autocomplete,
 * document upload picker, per-message model override (Shift+click),
 * and /spawn slash command.
 *
 * Enter sends, Shift+Enter inserts a newline.
 */

import {
  useCallback,
  useEffect,
  useRef,
  useState,
  type KeyboardEvent,
  type ChangeEvent,
} from "react";
import { Button, Icon, Select } from "@/design";
import type { Attachment, SkillTreeEntry } from "./chatApi";
import {
  applyMention,
  extractMentionQuery,
  searchSkills,
  type MentionQuery,
} from "./skillMention";
import styles from "./chats.module.css";

interface ChatComposerProps {
  onSend: (
    content: string,
    model: string | null,
    attachments: Attachment[],
  ) => Promise<void>;
  onUploadFiles: (files: File[]) => Promise<Array<{ name: string; path: string }>>;
  skills: SkillTreeEntry[];
  modelOptions: Array<{ value: string; label: string }>;
  sending: boolean;
  /** Whether the chat has a companion task (enables file uploads). */
  hasBoardTask: boolean;
}

export function ChatComposer({
  onSend,
  onUploadFiles,
  skills,
  modelOptions,
  sending,
  hasBoardTask,
}: ChatComposerProps) {
  const [draft, setDraft] = useState("");
  const [error, setError] = useState<string | null>(null);
  const [overrideModel, setOverrideModel] = useState<string>("");
  const [attachments, setAttachments] = useState<Attachment[]>([]);

  // Mention popover
  const [mentionQuery, setMentionQuery] = useState<MentionQuery | null>(null);
  const [mentionResults, setMentionResults] = useState<SkillTreeEntry[]>([]);
  const [mentionActive, setMentionActive] = useState(0);
  const [showMention, setShowMention] = useState(false);

  const textareaRef = useRef<HTMLTextAreaElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const mentionPopoverRef = useRef<HTMLDivElement>(null);

  // Auto-resize textarea
  useEffect(() => {
    const el = textareaRef.current;
    if (!el) return;
    el.style.height = "auto";
    el.style.height = `${Math.min(el.scrollHeight, 128)}px`;
  }, [draft]);

  // ── Mention detection ──

  const handleInputChange = useCallback(
    (e: ChangeEvent<HTMLTextAreaElement>) => {
      const value = e.target.value;
      setDraft(value);
      setError(null);

      const cursorPos = e.target.selectionStart ?? value.length;
      const query = extractMentionQuery(value, cursorPos);
      if (query) {
        setMentionQuery(query);
        const results = searchSkills(skills, query.query);
        setMentionResults(results);
        setMentionActive(0);
        setShowMention(results.length > 0);
      } else {
        setShowMention(false);
        setMentionQuery(null);
      }
    },
    [skills],
  );

  const insertMention = useCallback(
    (skill: SkillTreeEntry) => {
      if (!mentionQuery) return;
      const result = applyMention(draft, mentionQuery, skill);
      setDraft(result.text);
      setShowMention(false);
      setMentionQuery(null);

      // Add to attachments list
      setAttachments((prev) => [
        ...prev,
        { kind: "skill" as const, ref: skill.id, label: `@${skill.name}` },
      ]);

      // Refocus textarea at the correct position
      requestAnimationFrame(() => {
        if (textareaRef.current) {
          textareaRef.current.selectionStart = result.cursor;
          textareaRef.current.selectionEnd = result.cursor;
          textareaRef.current.focus();
        }
      });
    },
    [draft, mentionQuery],
  );

  // ── Keyboard handling ──

  const handleKeyDown = useCallback(
    (e: KeyboardEvent<HTMLTextAreaElement>) => {
      // Mention navigation
      if (showMention && mentionResults.length > 0) {
        if (e.key === "ArrowDown") {
          e.preventDefault();
          setMentionActive((prev) =>
            (prev + 1) % mentionResults.length,
          );
          return;
        }
        if (e.key === "ArrowUp") {
          e.preventDefault();
          setMentionActive((prev) =>
            (prev - 1 + mentionResults.length) % mentionResults.length,
          );
          return;
        }
        if (e.key === "Enter" || e.key === "Tab") {
          e.preventDefault();
          const skill = mentionResults[mentionActive];
          if (skill) insertMention(skill);
          return;
        }
        if (e.key === "Escape") {
          e.preventDefault();
          setShowMention(false);
          return;
        }
      }

      // Send on Enter (not Shift+Enter)
      if (e.key === "Enter" && !e.shiftKey) {
        e.preventDefault();
        void handleSend();
      }
    },
    [showMention, mentionResults, mentionActive, insertMention],
  );

  // Close mention popover on outside click
  useEffect(() => {
    if (!showMention) return;
    const handler = (e: MouseEvent) => {
      if (
        mentionPopoverRef.current &&
        !mentionPopoverRef.current.contains(e.target as Node) &&
        textareaRef.current &&
        !textareaRef.current.contains(e.target as Node)
      ) {
        setShowMention(false);
      }
    };
    document.addEventListener("mousedown", handler);
    return () => document.removeEventListener("mousedown", handler);
  }, [showMention]);

  // ── Send ──

  const handleSend = async () => {
    const content = draft.trim();
    if (!content || sending) return;

    // /spawn slash command: intercept as a spawn request
    if (content.startsWith("/spawn ")) {
      setError(null);
      try {
        const goal = content.slice("/spawn ".length).trim();
        const model = overrideModel || null;
        await onSend(content, model, attachments);
        setDraft("");
        setAttachments([]);
        setOverrideModel("");
      } catch (err) {
        setError(
          err instanceof Error ? err.message : "Failed to send message.",
        );
      }
      return;
    }

    setError(null);
    try {
      const model = overrideModel || null;
      await onSend(content, model, attachments);
      setDraft("");
      setAttachments([]);
      setOverrideModel("");
    } catch (err) {
      setError(
        err instanceof Error ? err.message : "Failed to send message.",
      );
    }
  };

  // ── File upload ──

  const handleFileSelect = useCallback(
    async (e: ChangeEvent<HTMLInputElement>) => {
      const files = Array.from(e.target.files ?? []);
      if (!files.length) return;
      try {
        const saved = await onUploadFiles(files);
        const newAttachments: Attachment[] = saved.map((s) => ({
          kind: "file" as const,
          ref: s.path,
          label: s.name,
        }));
        setAttachments((prev) => [...prev, ...newAttachments]);
      } catch (err) {
        setError(
          err instanceof Error ? err.message : "Could not upload files.",
        );
      }
      // Clear the input so the same file can be re-selected
      if (fileInputRef.current) fileInputRef.current.value = "";
    },
    [onUploadFiles],
  );

  const removeAttachment = useCallback((index: number) => {
    setAttachments((prev) => prev.filter((_, i) => i !== index));
  }, []);

  // ── Shift+click model override ──

  const handleModelShiftClick = useCallback(
    (e: React.MouseEvent) => {
      if (e.shiftKey) {
        // Toggle model override on shift+click for discoverability
        e.preventDefault();
      }
    },
    [],
  );

  return (
    <div className={styles.composer}>
      {/* Attachment chips */}
      {attachments.length > 0 && (
        <div className={styles.composerAttachments}>
          {attachments.map((att, i) => (
            <span key={`${att.kind}-${att.ref}-${i}`} className={styles.composerAttachmentChip}>
              {att.kind === "skill" ? "@" : "📎"} {att.label}
              <button
                className={styles.chipDismiss}
                onClick={() => removeAttachment(i)}
                aria-label={`Remove ${att.label}`}
              >
                ×
              </button>
            </span>
          ))}
        </div>
      )}

      {/* Textarea + mention popover */}
      <div className={styles.composerInputWrap}>
        <textarea
          ref={textareaRef}
          className={styles.composerInput}
          placeholder="Message… (@skill to attach, /spawn to fan out, Enter to send)"
          value={draft}
          onChange={handleInputChange}
          onKeyDown={handleKeyDown}
          disabled={sending}
          rows={1}
        />
        {showMention && mentionResults.length > 0 && mentionQuery && (
          <div
            ref={mentionPopoverRef}
            className={styles.mentionPopover}
            role="listbox"
          >
            {mentionResults.map((skill, i) => (
              <button
                key={skill.id}
                className={`${styles.mentionItem}${
                  i === mentionActive ? ` ${styles.mentionItemActive}` : ""
                }`}
                role="option"
                aria-selected={i === mentionActive}
                onClick={() => insertMention(skill)}
              >
                <span className={styles.mentionItemName}>
                  {skill.name}
                </span>
                {skill.description && (
                  <span className={styles.mentionItemDesc}>
                    {skill.description}
                  </span>
                )}
              </button>
            ))}
          </div>
        )}
      </div>

      {/* Controls row */}
      <div className={styles.composerRow}>
        <div className={styles.composerControls}>
          {/* Per-message model override (Shift+click) */}
          <div
            className={styles.dialogSelectWrap}
            onClick={handleModelShiftClick}
            title="Shift+click to override model for this message only"
          >
            <Select
              aria-label="Model override"
              value={overrideModel}
              onChange={(val) => setOverrideModel(val)}
              options={[
                { value: "", label: "Default" },
                ...modelOptions,
              ]}
            />
          </div>

          {/* Document upload */}
          {hasBoardTask && (
            <>
              <input
                ref={fileInputRef}
                type="file"
                multiple
                className={styles.composerHiddenInput}
                onChange={(e) => void handleFileSelect(e)}
                tabIndex={-1}
              />
              <Button
                variant="ghost"
                size="sm"
                onClick={() => fileInputRef.current?.click()}
                title="Attach files"
              >
                📎
              </Button>
            </>
          )}
        </div>

        <span className={styles.composerHint}>
          ⏎ send · ⇧⏎ newline
        </span>

        <Button
          variant="primary"
          size="sm"
          onClick={() => void handleSend()}
          disabled={sending || !draft.trim()}
          className={styles.composerSend}
        >
          {sending ? "Sending…" : "Send"}
        </Button>
      </div>

      {error && <span className={styles.composerError}>{error}</span>}
    </div>
  );
}

/* ── Chats v1 — CSS Modules ────────────────────────────────────
 * Two-pane layout: sidebar → thread, with collapsible right drawer.
 * Zero inline styles. Every color/spacing/font references design tokens.
 * Stripe/Apple bar: generous padding, hairline borders, small radii.
 */

/* ── Root layout ───────────────────────────────────────────── */

.container {
  display: flex;
  height: calc(100vh - var(--space-12));
  gap: 0;
  background: var(--canvas);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  overflow: hidden;
  position: relative;
}

/* ── Sidebar ───────────────────────────────────────────────── */

.sidebar {
  flex: 0 0 18rem;
  display: flex;
  flex-direction: column;
  border-right: 1px solid var(--border);
  background: var(--surface);
  min-width: 0;
  transition: flex-basis var(--motion-base) var(--ease);
}

.sidebarCollapsed {
  flex: 0 0 0;
  overflow: hidden;
  border-right: none;
}

.sidebarHeader {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--space-2);
  padding: var(--space-3) var(--space-4);
  border-bottom: 1px solid var(--border);
  min-height: 3.25rem;
  flex-shrink: 0;
}

.sidebarTitle {
  font-size: var(--text-small);
  font-weight: 600;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  color: var(--text-muted);
  margin: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.sidebarToggle {
  appearance: none;
  background: none;
  border: none;
  color: var(--text-muted);
  cursor: pointer;
  padding: var(--space-1);
  border-radius: var(--radius-sm);
  display: inline-flex;
  transition: color var(--motion-fast) var(--ease);
}

.sidebarToggle:hover {
  color: var(--text);
}

.sidebarToggle:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 1px;
}

.sidebarScroll {
  flex: 1;
  overflow-y: auto;
  padding: var(--space-2);
  display: flex;
  flex-direction: column;
  gap: var(--space-1);
}

/* Folder group */

.folderGroup {
  display: flex;
  flex-direction: column;
  gap: 1px;
}

.folderLabel {
  display: flex;
  align-items: center;
  gap: var(--space-2);
  padding: var(--space-2) var(--space-3);
  font-size: var(--text-micro);
  font-weight: 600;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  color: var(--text-faint);
  cursor: pointer;
  user-select: none;
  border-radius: var(--radius-sm);
  transition: color var(--motion-fast) var(--ease);
}

.folderLabel:hover {
  color: var(--text-muted);
}

.folderName {
  flex: 1;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.folderCount {
  font-size: var(--text-micro);
  color: var(--text-faint);
  font-weight: 400;
}

.folderDropTarget {
  border: 1px dashed var(--accent);
  border-radius: var(--radius-sm);
  background: color-mix(in srgb, var(--accent) 6%, transparent);
}

/* Chat item in sidebar */

.chatItem {
  display: flex;
  align-items: flex-start;
  gap: var(--space-2);
  padding: var(--space-2) var(--space-3);
  border-radius: var(--radius-md);
  cursor: pointer;
  user-select: none;
  transition: background-color var(--motion-fast) var(--ease);
  border: 1px solid transparent;
}

.chatItem:hover {
  background: color-mix(in srgb, var(--text) 4%, transparent);
}

.chatItemActive {
  background: color-mix(in srgb, var(--accent) 8%, transparent);
  border-color: color-mix(in srgb, var(--accent) 20%, var(--border));
}

.chatItemDragging {
  opacity: 0.5;
}

.chatItemContent {
  flex: 1;
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.chatItemTitle {
  font-size: var(--text-small);
  font-weight: 500;
  color: var(--text);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.chatItemMeta {
  font-size: var(--text-micro);
  color: var(--text-faint);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.chatItemBadge {
  flex-shrink: 0;
  margin-top: 2px;
}

/* New chat button */

.newChatBtn {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: var(--space-2);
  padding: var(--space-2) var(--space-3);
  margin: var(--space-2);
  border: 1px dashed var(--border-strong);
  border-radius: var(--radius-md);
  background: none;
  color: var(--text-muted);
  font-family: var(--font-sans);
  font-size: var(--text-small);
  font-weight: 500;
  cursor: pointer;
  transition: all var(--motion-fast) var(--ease);
}

.newChatBtn:hover {
  border-color: var(--accent);
  color: var(--accent);
  background: color-mix(in srgb, var(--accent) 4%, transparent);
}

.newChatBtn:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 1px;
}

/* ── Main area ─────────────────────────────────────────────── */

.mainArea {
  flex: 1;
  display: flex;
  flex-direction: column;
  min-width: 0;
  background: var(--canvas);
}

.mainToolbar {
  display: flex;
  align-items: center;
  gap: var(--space-2);
  padding: var(--space-2) var(--space-4);
  border-bottom: 1px solid var(--border);
  background: var(--surface);
  min-height: 3.25rem;
  flex-shrink: 0;
}

.toolbarSpacer {
  flex: 1;
}

/* ── Chat header ───────────────────────────────────────────── */

.header {
  display: flex;
  align-items: center;
  gap: var(--space-3);
  padding: var(--space-3) var(--space-4);
  border-bottom: 1px solid var(--border);
  background: var(--surface);
  flex-shrink: 0;
  min-height: 3.5rem;
}

.headerTitleWrap {
  flex: 1;
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.headerTitleInput {
  appearance: none;
  border: none;
  background: transparent;
  color: var(--text);
  font-family: var(--font-sans);
  font-size: var(--text-h3);
  font-weight: 600;
  padding: 0;
  outline: none;
  width: 100%;
}

.headerTitleInput:focus {
  border-bottom: 1px solid var(--accent);
}

.headerTitleDisplay {
  font-size: var(--text-h3);
  font-weight: 600;
  color: var(--text);
  cursor: pointer;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  padding: var(--space-1) 0;
  border-bottom: 1px solid transparent;
  transition: border-color var(--motion-fast) var(--ease);
}

.headerTitleDisplay:hover {
  border-bottom-color: var(--border);
}

.headerSubline {
  font-size: var(--text-micro);
  color: var(--text-faint);
  display: flex;
  align-items: center;
  gap: var(--space-2);
}

.headerActions {
  display: flex;
  align-items: center;
  gap: var(--space-2);
  flex-shrink: 0;
}

.headerDivider {
  width: 1px;
  height: 1.25rem;
  background: var(--border);
}

/* ── Thread ────────────────────────────────────────────────── */

.threadContainer {
  flex: 1;
  display: flex;
  flex-direction: column;
  min-height: 0;
  overflow: hidden;
}

.threadScroll {
  flex: 1;
  overflow-y: auto;
  padding: var(--space-4) var(--space-5);
  display: flex;
  flex-direction: column;
  gap: var(--space-3);
  scroll-behavior: smooth;
}

/* Message rows */

.msg {
  display: flex;
  flex-direction: column;
  gap: var(--space-1);
  max-width: 85%;
  animation: msgFadeIn var(--motion-base) var(--ease);
}

.msgUser {
  align-self: flex-end;
}

.msgAgent {
  align-self: flex-start;
}

.msgSystem {
  align-self: center;
  max-width: 95%;
}

.msgBubble {
  padding: var(--space-3) var(--space-4);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  background: var(--surface);
  transition: background-color var(--motion-fast) var(--ease);
}

.msgUser .msgBubble {
  border-color: var(--accent);
  background: color-mix(in srgb, var(--accent) 4%, var(--surface));
}

.msgSystem .msgBubble {
  border-style: dashed;
  background: transparent;
  font-size: var(--text-small);
  opacity: 0.85;
}

.msgAgent .msgBubble {
  background: var(--surface-raised);
}

.msgHead {
  display: flex;
  align-items: center;
  gap: var(--space-2);
  font-size: var(--text-micro);
  color: var(--text-muted);
  padding: 0 var(--space-1);
}

.msgRole {
  font-weight: 600;
  color: var(--text);
  text-transform: capitalize;
}

.msgAgent .msgRole {
  color: var(--accent);
}

.msgBody {
  white-space: pre-wrap;
  word-break: break-word;
  color: var(--text);
  line-height: 1.6;
  font-size: var(--text-small);
}

/* Streaming delta cursor */

.streamCursor {
  display: inline-block;
  width: 2px;
  height: 1em;
  background: var(--accent);
  margin-left: 2px;
  vertical-align: text-bottom;
  animation: blink 1s var(--ease) infinite;
}

/* State chips */

.stateChip {
  display: inline-flex;
  align-items: center;
  gap: var(--space-1);
  padding: var(--space-1) var(--space-2);
  border-radius: var(--radius-pill);
  font-size: var(--text-micro);
  font-weight: 500;
  border: 1px solid transparent;
  transition: all var(--motion-fast) var(--ease);
}

.stateChipQueued {
  color: var(--text-muted);
  background: color-mix(in srgb, var(--text-muted) 10%, transparent);
  border-color: color-mix(in srgb, var(--text-muted) 20%, transparent);
}

.stateChipRunning {
  color: var(--running);
  background: color-mix(in srgb, var(--running) 10%, transparent);
  border-color: color-mix(in srgb, var(--running) 20%, transparent);
}

.stateChipDone {
  color: var(--ok);
  background: color-mix(in srgb, var(--ok) 10%, transparent);
  border-color: color-mix(in srgb, var(--ok) 20%, transparent);
}

/* Tool call card */

.toolCallCard {
  padding: var(--space-2) var(--space-3);
  border: 1px solid var(--border);
  border-left: 3px solid var(--accent);
  border-radius: var(--radius-sm);
  background: var(--surface-raised);
  font-family: var(--font-mono);
  font-size: var(--text-micro);
  color: var(--text-muted);
  margin-top: var(--space-1);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.toolCallLabel {
  color: var(--accent);
  font-weight: 600;
  margin-right: var(--space-2);
}

/* Attachment pills */

.attachmentRow {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-1);
  padding: 0 var(--space-1);
}

.attachmentPill {
  display: inline-flex;
  align-items: center;
  gap: var(--space-1);
  padding: 2px var(--space-2);
  border-radius: var(--radius-pill);
  font-size: var(--text-micro);
  color: var(--text-muted);
  background: color-mix(in srgb, var(--text-muted) 8%, transparent);
  border: 1px solid color-mix(in srgb, var(--text-muted) 16%, transparent);
}

/* ── Composer ──────────────────────────────────────────────── */

.composer {
  padding: var(--space-3) var(--space-4);
  border-top: 1px solid var(--border);
  background: var(--surface);
  display: flex;
  flex-direction: column;
  gap: var(--space-2);
  flex-shrink: 0;
}

.composerInput {
  width: 100%;
  min-height: 3rem;
  max-height: 8rem;
  resize: none;
  padding: var(--space-2) var(--space-3);
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  background: var(--canvas);
  color: var(--text);
  font-family: var(--font-sans);
  font-size: var(--text-small);
  line-height: 1.5;
  transition: border-color var(--motion-fast) var(--ease);
}

.composerInput:focus {
  outline: none;
  border-color: var(--accent);
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--accent) 12%, transparent);
}

.composerInput:disabled {
  opacity: 0.6;
  cursor: not-allowed;
}

.composerInput::placeholder {
  color: var(--text-faint);
}

.composerInputWrap {
  position: relative;
  width: 100%;
}

.composerHiddenInput {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip-path: inset(50%);
  white-space: nowrap;
}

.composerRow {
  display: flex;
  align-items: center;
  gap: var(--space-2);
  flex-wrap: wrap;
}

.composerControls {
  display: flex;
  align-items: center;
  gap: var(--space-2);
  flex: 1;
  min-width: 0;
}

.composerSend {
  flex-shrink: 0;
}

.composerHint {
  font-size: var(--text-micro);
  color: var(--text-faint);
}

.composerError {
  font-size: var(--text-small);
  color: var(--danger);
  padding: 0 var(--space-1);
}

/* Attachment chips in composer */

.composerAttachments {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-1);
  padding: 0 var(--space-1);
}

.composerAttachmentChip {
  display: inline-flex;
  align-items: center;
  gap: var(--space-1);
  padding: 2px var(--space-2);
  border-radius: var(--radius-pill);
  font-size: var(--text-micro);
  color: var(--accent);
  background: color-mix(in srgb, var(--accent) 8%, transparent);
  border: 1px solid color-mix(in srgb, var(--accent) 20%, transparent);
}

.chipDismiss {
  appearance: none;
  background: none;
  border: none;
  color: inherit;
  cursor: pointer;
  padding: 0;
  line-height: 1;
  display: inline-flex;
  opacity: 0.7;
  transition: opacity var(--motion-fast) var(--ease);
}

.chipDismiss:hover {
  opacity: 1;
}

/* Skill mention popover */

.mentionPopover {
  position: absolute;
  z-index: var(--z-dropdown);
  background: var(--surface-raised);
  border: 1px solid var(--border-strong);
  border-radius: var(--radius-md);
  box-shadow: var(--shadow-md);
  max-height: 12rem;
  overflow-y: auto;
  min-width: 14rem;
  padding: var(--space-1);
}

.mentionItem {
  display: flex;
  align-items: center;
  gap: var(--space-2);
  width: 100%;
  appearance: none;
  background: none;
  border: none;
  border-radius: var(--radius-sm);
  padding: var(--space-2) var(--space-3);
  font-family: var(--font-sans);
  font-size: var(--text-small);
  color: var(--text);
  cursor: pointer;
  text-align: left;
  transition: background-color var(--motion-fast) var(--ease);
}

.mentionItem:hover,
.mentionItemActive {
  background: color-mix(in srgb, var(--accent) 12%, transparent);
}

.mentionItem:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: -2px;
}

.mentionItemName {
  font-weight: 600;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.mentionItemDesc {
  color: var(--text-faint);
  font-size: var(--text-micro);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  flex: 1;
  min-width: 0;
}

/* ── Right drawer (workspace) ──────────────────────────────── */

.drawer {
  flex: 0 0 24rem;
  display: flex;
  flex-direction: column;
  border-left: 1px solid var(--border);
  background: var(--surface);
  min-width: 0;
  transition: flex-basis var(--motion-base) var(--ease);
  overflow: hidden;
}

.drawerCollapsed {
  flex: 0 0 0;
  border-left: none;
}

.drawerHeader {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--space-2);
  padding: var(--space-3) var(--space-4);
  border-bottom: 1px solid var(--border);
  min-height: 3.25rem;
  flex-shrink: 0;
}

.drawerTitle {
  font-size: var(--text-small);
  font-weight: 600;
  color: var(--text);
  margin: 0;
}

.drawerContent {
  flex: 1;
  overflow-y: auto;
  min-height: 0;
}

.drawerContentInner {
  display: flex;
  flex-direction: column;
  height: 100%;
  width: 100%;
}

/* Workspace tabs inside the drawer */

.workspaceTabs {
  display: flex;
  gap: 1px;
  background: var(--border);
  overflow: hidden;
  flex-shrink: 0;
}

.workspaceTab {
  flex: 1;
  padding: var(--space-2) var(--space-4);
  border: none;
  background: var(--surface);
  color: var(--text-muted);
  font-family: var(--font-sans);
  font-size: var(--text-small);
  font-weight: 400;
