"use client";

/**
 * WorkspaceTabs — Activity Log + Live Terminal tabs for the right drawer.
 *
 * Renders inside the collapsible right drawer on the chats page.
 * Resolves the active session for a given task/project to feed the
 * TerminalView with a live transcript stream.
 */

import { useEffect, useState } from "react";
import { Button, EmptyState, Icon, Select } from "@/design";
import { api } from "@/lib/api";
import { collabApi } from "@/features/collab/client";
import { SessionFollow } from "./SessionFollow";
import { TerminalView } from "./TerminalView";
import type { Session } from "@/lib/contracts";
import styles from "./chats.module.css";

interface WorkspaceTabsProps {
  taskId?: string | null;
  projectId?: string | null;
  projectName?: string | null;
}

export function WorkspaceTabs({
  taskId,
  projectId,
  projectName,
}: WorkspaceTabsProps) {
  const [activeTab, setActiveTab] = useState<"activity" | "terminal">(
    "activity",
  );
  const [selectedSessionId, setSelectedSessionId] = useState<string>("");
  const [, setSessions] = useState<Session[]>([]);

  const fetchAllSessions = async () => {
    try {
      const list = await api.sessions();
      const sorted = [...list].sort(
        (a, b) =>
          Date.parse(b.created_at || "0") -
          Date.parse(a.created_at || "0"),
      );
      setSessions(sorted);
      return sorted;
    } catch (err) {
      console.error("Failed to load sessions in WorkspaceTabs:", err);
      return [];
    }
  };

  useEffect(() => {
    const init = async () => {
      const allSess = await fetchAllSessions();
      if (allSess.length === 0) {
        setSelectedSessionId("");
        return;
      }

      if (taskId) {
        try {
          const taskSessions = await collabApi.fetchTaskSessions(taskId);
          const liveId =
            taskSessions.live_session_id ||
            taskSessions.sessions?.[
              taskSessions.sessions.length - 1
            ]?.id ||
            null;
          if (liveId && allSess.some((s) => s.id === liveId)) {
            setSelectedSessionId(liveId);
            return;
          }
        } catch (e) {
          console.debug(
            "Failed fetching task sessions in WorkspaceTabs fallback:",
            e,
          );
        }
      }

      if (projectId || projectName) {
        const queryProject = (projectId || "").toLowerCase();
        const queryName = (projectName || "").toLowerCase();
        const matched = allSess.find((s) => {
          const dir = (s.project_dir || "").toLowerCase();
          const title = (s.title || "").toLowerCase();
          return (
            (queryProject && dir.includes(queryProject)) ||
            (queryName &&
              (dir.includes(queryName) || title.includes(queryName)))
          );
        });
        if (matched) {
          setSelectedSessionId(matched.id);
          return;
        }
      }

      setSelectedSessionId(allSess[0].id);
    };

    void init();
  }, [taskId, projectId, projectName]);

  return (
    <div className={styles.drawerContentInner}>
      <div className={styles.workspaceTabs}>
        <button
          className={`${styles.workspaceTab}${activeTab === "activity" ? ` ${styles.workspaceTabActive}` : ""}`}
          onClick={() => setActiveTab("activity")}
        >
          Activity
        </button>
        <button
          className={`${styles.workspaceTab}${activeTab === "terminal" ? ` ${styles.workspaceTabActive}` : ""}`}
          onClick={() => setActiveTab("terminal")}
        >
          Terminal
        </button>
      </div>

      <div className={styles.workspaceTabPanel}>
        {activeTab === "activity" ? (
          <SessionFollow
            taskId={taskId}
            projectId={projectId}
            projectName={projectName}
          />
        ) : selectedSessionId ? (
          <TerminalView sessionId={selectedSessionId} />
        ) : (
          <EmptyState
            title="No active session"
            message="Terminal will stream here when an agent session starts."
          />
        )}
      </div>
    </div>
  );
}

